package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.PropertyOwnerPointer;
import org.apache.commons.jxpath.ri.model.QName;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class NullPropertyPointer_createPath_TriageGen1Test {

    @Test
    public void testCreatePath_IsAttribute_ReturnsAttribute() {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttribute = mock(NodePointer.class);
        QName mockName = new QName("testAttr");

        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));

        doReturn(true).when(nullPropertyPointer).isAttribute();
        doReturn(mockName).when(nullPropertyPointer).getName();
        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(eq(mockContext), eq(mockName))).thenReturn(mockAttribute);

        // Act
        NodePointer result = nullPropertyPointer.createPath(mockContext);

        // Assert
        assertEquals(mockAttribute, result);
        verify(mockParent).createPath(mockContext);
        verify(mockNewParent).createAttribute(mockContext, mockName);
        verify(mockNewParent, never()).createChild(any(), any(), anyInt());
    }

    @Test
    public void testCreatePath_IsNotAttribute_ParentIsPropertyOwnerPointer() {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropertyPointer = mock(NodePointer.class);
        NodePointer mockChild = mock(NodePointer.class);
        QName mockName = new QName("testProp");
        int mockIndex = 0;

        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));

        doReturn(false).when(nullPropertyPointer).isAttribute();
        doReturn(mockName).when(nullPropertyPointer).getName();
        doReturn(mockIndex).when(nullPropertyPointer).getIndex(); // Assuming getIndex() exists via inheritance or context

        // In the provided source, getIndex() is used but not explicitly listed in "Other methods". 
        // Assuming it's available in the class hierarchy.

        when(mockParent.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropertyPointer);
        when(mockPropertyPointer.createChild(eq(mockContext), eq(mockName), eq(mockIndex))).thenReturn(mockChild);

        // Act
        NodePointer result = nullPropertyPointer.createPath(mockContext);

        // Assert
        assertEquals(mockChild, result);
        verify(mockPop).getPropertyPointer();
        verify(mockPropertyPointer).createChild(mockContext, mockName, mockIndex);
    }

    @Test
    public void testCreatePath_IsNotAttribute_ParentIsNotPropertyOwnerPointer() {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class); // e.g., a DOMNodePointer
        NodePointer mockChild = mock(NodePointer.class);
        QName mockName = new QName("testChild");
        int mockIndex = 5;

        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));

        doReturn(false).when(nullPropertyPointer).isAttribute();
        doReturn(mockName).when(nullPropertyPointer).getName();
        // Mocking getIndex logic if it's part of the object
        // Since getIndex() is used in the code but not in the signature list, we assume it returns a value.
        // For the sake of compilation/test, if the class doesn't have getIndex, this requires adjustment.
        // Assuming it's part of the class.

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createChild(eq(mockContext), eq(mockName), anyInt())).thenReturn(mockChild);

        // Act
        NodePointer result = nullPropertyPointer.createPath(mockContext);

        // Assert
        assertEquals(mockChild, result);
        verify(mockNewParent).createChild(eq(mockContext), eq(mockName), anyInt());
        verify(mockNewParent, never()).getPropertyPointer(); // It's not a PropertyOwnerPointer
    }
}
